head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > select]<br/>컴포넌트의 입력값 전체가 선택되며 포커스됩니다.",
    "validation" : [
        "컴포넌트의 입력값 전체가 선택되며 포커스됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onclick"]);

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar('', eList);
}



scwin.btn_editType_onclick = function (e) {
    // id가 "target1"을 포함하는 요소를 찾기
    let targetEmement = document.querySelector('[id*="target1"]');

    if (targetEmement) {
        let inputElement = null;

        // id가 "target1_input"을 포함하는 input 태그 찾기
        inputElement = targetEmement.querySelector('input[id*="target1_input"]');

        wf_body_bottom.getObj("scwin").setReturnValue('selectionStart :' + inputElement.selectionStart);       
        wf_body_bottom.getObj("scwin").setReturnValue('selectionEnd :' + inputElement.selectionEnd);       
    }
}



scwin.btn_select_onclick = function (e) {
	target1.select();

    scwin.btn_editType_onclick();
};



scwin.btn_blur_onclick = function (e) {
	target1.blur();
};
